/**
 * One brand icon, sized and aligned exactly as the webfont drew it.
 * An unknown name returns an empty string rather than a broken box.
 */
function brand_icon(string $name, string $extraClass = ''): string
{
    if (!isset(BRAND_ICONS[$name])) {
        return '';
    }
    $i  = BRAND_ICONS[$name];
    $em = round($i['w'] / 512, 4);   // Font Awesome's em square is 512 units
    $cls = trim('brand-icon ' . $extraClass);

    return '<i class="' . htmlspecialchars($cls, ENT_QUOTES, 'UTF-8') . '" aria-hidden="true">'
         . '<svg xmlns="http://www.w3.org/2000/svg" viewBox="' . $i['vb'] . '" '
         . 'width="' . $em . 'em" height="1em" fill="currentColor" '
         . 'style="vertical-align:-.125em;display:inline-block" focusable="false">'
         . '<path d="' . $i['d'] . '"/></svg></i>';
}
